import * as inspector from 'node:inspector/promises'
import { logger } from '../logger'
import { FileSystem, path } from '@servicenow/sdk-build-core'

// These values come from the Chrome DevTools Protocol:
// https://chromedevtools.github.io/devtools-protocol/tot/Profiler/
const PROFILER_ENABLE = 'Profiler.enable'
const PROFILER_START = 'Profiler.start'
const PROFILER_STOP = 'Profiler.stop'
const PROFILER_DISABLE = 'Profiler.disable'

async function startProfiling(session: inspector.Session) {
    session.connect()
    await session.post(PROFILER_ENABLE)
    await session.post(PROFILER_START)
    logger.info('Profiling started')
}

async function stopProfiling(session: inspector.Session) {
    const { profile } = (await session.post(PROFILER_STOP)) as { profile: inspector.Profiler.Profile }
    await session.post(PROFILER_DISABLE)
    session.disconnect()
    return profile
}

async function writeProfilingResults(name: string, fs: FileSystem, profile: inspector.Profiler.Profile) {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
    const outputPath = path.resolve(`${name}-${timestamp}.cpuprofile`)
    const dir = path.dirname(outputPath)
    if (!FileSystem.existsSync(fs, dir)) {
        fs.mkdirSync(dir, { recursive: true })
    }

    fs.writeFileSync(outputPath, JSON.stringify(profile))
    logger.info(`Profile written to ${outputPath}`)
}

export async function withProfiling<T>(
    enabled: boolean,
    name: string,
    fs: FileSystem,
    fn: () => Promise<T>
): Promise<T> {
    if (!enabled) {
        return fn()
    }

    const session = new inspector.Session()
    await startProfiling(session)
    try {
        return await fn()
    } finally {
        const profile = await stopProfiling(session)
        await writeProfilingResults(name, fs, profile)
    }
}
